# IFR weather theory: Aviation Weather Handbook FAA-H-8083-28A (icing, fog, fronts, turbulence,
# thunderstorms), AIM 7-1-27 thunderstorm flying, AC 91-74 (icing). ACS area I.B.K3.
ITEMS = [
    # ---------- Practice Test 1 ----------
    S(1, 2, "Icing types", "Which ice forms from small supercooled droplets that freeze the instant they strike the airplane?",
      ["Rime ice", "Clear ice", "Hoar frost"],
      "Rime ice is rough, milky and opaque, made by small supercooled droplets freezing on impact. Clear ice forms from large drops that freeze slowly and spread back over the surface."),
    S(1, 3, "Freezing rain", "Freezing rain is falling at your cruise altitude. What does that tell you about the air above you?",
      ["Warmer air above, above freezing", "Colder air above, below freezing", "A layer of dry air with no clouds"],
      "Freezing rain forms when rain from an above-freezing layer falls into a sub-freezing layer below. Climbing into the warmer layer is often the way out."),
    S(1, 2, "Warm front", "Which conditions are typical ahead of a warm front with stable, moist air?",
      ["Low stratus and steady rain", "Towering cumulus and short heavy showers", "Clear skies and gusty northwest winds"],
      "Warm air gliding up over the cold air ahead of a warm front gives wide areas of stratiform cloud, steady precipitation, low ceilings and fog, often IFR for hundreds of miles."),
    S(1, 2, "Fog formation", "At dusk the temperature-dewpoint spread at your destination is narrowing to a few degrees. What does that warn of?",
      ["Fog or very low stratus", "Clear air turbulence aloft", "Hail from building storms"],
      "When the air cools toward its dewpoint, it nears saturation. A small and shrinking spread, around 5 degrees F (3 degrees C) or less, means fog or very low cloud is likely, especially on a calm, clear night."),
    S(1, 3, "Icing in clouds", "Where is structural icing usually most severe in a large cumuliform cloud above the freezing level?",
      ["In the updrafts", "Only near the cloud base", "In the thin anvil at the top"],
      "Strong updrafts in cumuliform clouds carry large supercooled drops high above the freezing level, so icing there can be rapid and of the clear type."),
    S(1, 2, "Thunderstorm avoidance", "Why should you avoid flying under the anvil of a thunderstorm?",
      ["Hail can fall from it miles from the core", "Its updrafts carry you into the cloud tops", "It is always surrounded by dense fog"],
      "The AIM warns not to fly under a thunderstorm even if you can see through it. Hail can fall from the overhanging anvil, well away from the core and the heavy rain."),
    S(1, 3, "Mountain obscuration", "Moist, stable air pushed up a gently rising plain forms what kind of fog?",
      ["Upslope fog", "Radiation fog", "Steam fog"],
      "Upslope fog forms as stable, moist air is lifted and cooled adiabatically along rising terrain. It can be widespread and last for long periods."),
    # ---------- Practice Test 2 ----------
    S(2, 2, "Icing types", "Clear ice is most likely when you fly through:",
      ["Large drops near freezing", "Small droplets at minus 20 degrees C", "Dry snow at very cold temperatures"],
      "Clear ice forms from large supercooled drops at temperatures near freezing, where each drop freezes slowly and spreads back. It is glossy, heavy and hard to remove."),
    S(2, 2, "Stratiform icing", "In widespread stratiform cloud above the freezing level, icing usually:",
      ["Covers wide areas in shallow layers", "Is the most severe icing of any cloud type", "Occurs only inside embedded showers"],
      "Stratiform clouds have weak vertical motion, so icing tends to be lighter but can extend over a wide area. A change of a few thousand feet often leaves the icing layer."),
    S(2, 3, "Occluded front", "An occluded front often brings what mix of weather?",
      ["Stratus with embedded storms", "Clear skies and light winds only", "A single line of fair-weather cumulus"],
      "An occlusion combines cold-front and warm-front weather: widespread stratiform cloud and precipitation that can hide embedded thunderstorms, a serious IFR hazard."),
    S(2, 2, "Steam fog", "Very cold air moving over much warmer water tends to form:",
      ["Steam fog", "Advection fog", "Ice fog"],
      "Steam fog forms when water evaporates from a warm surface into cold air above it. Low-level turbulence and icing can occur in it."),
    S(2, 3, "Frontal fog", "Rain falling from warmer air into a cooler layer below can saturate that layer. What forms?",
      ["Frontal fog", "Radiation fog", "Upslope fog"],
      "Precipitation-induced (frontal) fog forms when warm rain evaporates into cooler air near the ground, often ahead of a warm front. It can be thick and widespread."),
    S(2, 2, "Embedded storms", "Why are embedded thunderstorms a special hazard in IFR flight?",
      ["Other cloud hides them from view", "They never produce lightning", "They form only above 30,000 feet"],
      "Embedded thunderstorms are hidden inside layers of stratiform cloud, so a pilot in IMC cannot see them. Radar or ATC information is needed to stay clear."),
    S(2, 3, "Tailplane icing", "Tailplane stall from ice is most likely right after you:",
      ["Extend the flaps on approach", "Retract the gear after takeoff", "Level off at cruise altitude"],
      "Extending flaps increases the downwash on the horizontal tail and its negative angle of attack, so an ice-contaminated tailplane may stall then. The nose pitches down abruptly."),
    # ---------- Drill only ----------
    S(0, 2, "Icing types", "Mixed ice is best described as:",
      ["Rime and clear ice forming together", "Frost that melts during the climb", "Ice that forms only on the propeller"],
      "Mixed ice forms when drop sizes vary or snow and ice particles are caught in clear ice. It has the rough shape of rime and the hardness of clear ice."),
    S(0, 3, "Supercooled large drops", "Why are supercooled large drops especially dangerous?",
      ["They run back past deicing boots", "They freeze only on the windshield", "They form only on the top surfaces"],
      "Large drops do not freeze at once, so they flow aft and freeze behind the protected leading edges, where boots and heated surfaces cannot remove the ice."),
    S(0, 2, "Freezing level", "On a climb through cloud, at what outside air temperature should you first expect structural icing?",
      ["At 0 degrees C or colder", "Only below minus 15 degrees C", "Only below minus 40 degrees C"],
      "Structural ice can form whenever the airframe is at or below freezing in visible moisture, starting at 0 degrees C. Below about minus 40 degrees C water is almost always frozen already."),
    S(0, 3, "Thunderstorm avoidance", "When a thunderstorm can't be avoided, why fly a heading straight through it?",
      ["To spend the least time in it", "To keep the radar picture steady", "To stay above its freezing level"],
      "The AIM advises holding a heading that takes you through the storm in the least time, keeping attitude, not altitude, and turning the cockpit lights up to limit lightning blindness."),
    S(0, 2, "Thunderstorm avoidance", "In a thunderstorm, what does the AIM say to hold?",
      ["A constant attitude", "A constant altitude", "A constant airspeed of VNE"],
      "The AIM says to maintain a constant attitude and let the airplane ride the drafts. Chasing altitude adds stress to the airframe."),
    S(0, 2, "Turbulence", "Clear air turbulence is most often found:",
      ["Near the jet stream", "Inside stratus layers", "Over calm warm oceans"],
      "Clear air turbulence occurs in strong wind shear without cloud, most often near the jet stream and on its cold side, and near upper troughs."),
    S(0, 3, "Low-level wind shear", "On a clear night, a strong radiation inversion with strong winds above it can cause:",
      ["Wind shear near the inversion top", "Icing near the ground in clear air", "A steady headwind all the way down"],
      "Below a strong surface inversion the air is calm, while winds above may be strong. Climbing or descending through the inversion top can bring a sudden change in airspeed."),
    S(0, 2, "Volcanic ash", "Why must volcanic ash clouds be avoided?",
      ["It can stop the engines", "It causes only light rime icing", "It raises the stall speed slightly"],
      "Ash melts in hot engine sections and can flame out engines, abrades windscreens and blocks pitot tubes. It is a SIGMET hazard and should never be entered."),
    S(0, 2, "Air mass stability", "Which feature points to unstable air on an IFR flight?",
      ["Showers and turbulence", "Steady drizzle and smooth air", "Layered fog under an inversion"],
      "Unstable air brings cumuliform clouds, showery precipitation, turbulence and good visibility outside showers. Stable air gives stratus, steady rain and smooth air."),
    S(0, 3, "Frontal passage", "Which pair of changes shows that a front has passed?",
      ["Wind shift and temperature change", "Rising humidity and calm winds", "Steady pressure and steady temperature"],
      "A front is a boundary between air masses, so its passage brings a shift in wind direction and a change in temperature, dewpoint and pressure trend."),
]
